@layer components {
  /* Field: ui-sdk's stylesheet stacks the label, the control, and the texts. These set the ViteHub text sizes. */
  [data-slot="field-label"] {
    color: var(--vh-text);
    font-size: 0.875rem;
    font-weight: 500;
  }

  [data-slot="field-description"] {
    color: var(--vh-muted);
    font-size: 0.8125rem;
  }

  [data-slot="field-error"] {
    color: var(--vh-text-error, var(--vh-error));
    font-size: 0.8125rem;
  }
}

export { default as Field } from "./Field.vue";
export { default as FieldDescription } from "./FieldDescription.vue";
export { default as FieldError } from "./FieldError.vue";
export { default as FieldLabel } from "./FieldLabel.vue";
export type * from "./types.ts";

export interface FieldProps {
  invalid?: boolean;
  disabled?: boolean;
}

export interface FieldSlots {
  default?: () => unknown;
}

export interface FieldLabelProps {
  label?: string;
}

export interface FieldLabelSlots {
  default?: () => unknown;
}

export interface FieldDescriptionSlots {
  default?: () => unknown;
}

export interface FieldErrorSlots {
  default?: () => unknown;
}
